/**
 * Joi validation schema for the `project` JSONB column in bng.projects.
 *
 * Generated by /reflect-schema from a sample row. Update by re-running the
 * skill after schema changes, or edit manually as requirements become clearer.
 *
 * The `.description()` on every key is the source of prose for the generated
 * data dictionary (`npm run data-dictionary` → data-dictionary/data-dictionary.md) and for
 * the Swagger UI. Keep them accurate: they document what is actually persisted.
 */
import Joi from 'joi'

import {
  habitatSizesSummarySchema,
  baselineUnitsTotalsSchema,
  featureIdDescription,
  BASELINE_STRATEGIC_SIGNIFICANCE_DESCRIPTION,
  redLineSchema,
  featureDataEnvelopeFields
} from './project-shared-schemas.js'
import { postInterventionDataSchema } from './post-intervention/project-post-intervention-schema.js'
import { listedFileText, longFileText, shortFileText } from './text-joi.js'

const BASELINE_STATUS_DESCRIPTION =
  "'Complete' when units were successfully calculated; otherwise 'Incomplete'."

const DISTINCTIVENESS_SCORE_DESCRIPTION =
  'Numeric distinctiveness score for the band, from bng-library/metric.'

// Survey / provenance / planning metadata columns shared by the Habitats,
// Hedgerows and Rivers layers. Promoted to named fields by BMD-498. Returned as
// a fresh object each call because Joi schema objects are stateful and must not
// be shared between parent schemas.
const metadataSchemaKeys = () => ({
  siteName: longFileText().description(
    'Site name from the GeoPackage (Site Name column).'
  ),
  surveyDate: Joi.string()
    .allow(null, '')
    .description(
      'Survey date from the GeoPackage (Survey Date column), as stored in the source file.'
    ),
  surveyDetails: longFileText().description(
    'Free-text survey details from the GeoPackage.'
  ),
  comment: longFileText().description(
    'Free-text comment from the GeoPackage (Comment column on area and tree habitats, Comments on hedgerows and watercourses), with leading and trailing whitespace removed. A legacy file uploaded as baseline and post-intervention together leaves this null on an Enhanced or Created row, because that comment is stored on the post-intervention habitat. A baseline-only upload keeps it. A BNG Service template file keeps the comment from its Baseline table. A blank comment is null.'
  ),
  mappedBy: longFileText().description(
    'Name of the surveyor who mapped the feature (Mapped by).'
  ),
  company: longFileText().description(
    'Company responsible for the survey (Company column).'
  ),
  baseMap: longFileText().description(
    'Base map used during mapping (Base Map column).'
  ),
  location: listedFileText('location').description(
    "Location from the GeoPackage (Location column). One of the values the template's Location list offers, as the upload checks it, or blank."
  ),
  spatialRiskCategory: listedFileText('spatialRiskCategory').description(
    'Spatial risk category from the GeoPackage.'
  ),
  habitatCreatedInAdvanceYears: listedFileText(
    'habitatCreatedInAdvanceYears'
  ).description(
    'Years the habitat was created in advance, from the GeoPackage (Habitat created in advance/years).'
  ),
  delayInStartingHabitatCreationYears: listedFileText(
    'delayInStartingHabitatCreationYears'
  ).description(
    'Years of delay before starting habitat creation, from the GeoPackage (Delay in starting habitat creation/years).'
  ),
  rawDistinctiveness: listedFileText('rawDistinctiveness').description(
    'Raw distinctiveness value as written in the GeoPackage — the Baseline Distinctiveness column for the baseline document, the Proposed Distinctiveness column for the post-intervention document. Informational only; the authoritative distinctiveness band is the `distinctiveness` field resolved by bng-library/metric.'
  )
})

const RETENTION_CATEGORY_DESCRIPTION = 'Retention category from the GeoPackage.'

const siteSchema = Joi.object({
  name: Joi.string().description('Free-text name of the development site.'),
  grid_ref: Joi.string().description(
    'Ordnance Survey national grid reference for the site.'
  )
}).description('Development site details.')

const unitsSchema = Joi.object({
  habitat: Joi.number().description(
    'Project-level area-habitat biodiversity unit total.'
  ),
  hedgerow: Joi.number().description(
    'Project-level hedgerow biodiversity unit total.'
  ),
  watercourse: Joi.number().description(
    'Project-level watercourse biodiversity unit total.'
  )
}).description('Project-level biodiversity unit summary.')

const habitatSchema = Joi.object({
  featureId: Joi.string()
    .uuid()
    .required()
    .description(featureIdDescription('bng.baseline_habitats')),
  ref: shortFileText().description(
    'Parcel reference from the GeoPackage (Parcel Ref column).'
  ),
  type: shortFileText().description(
    "Baseline habitat type, e.g. 'Lowland meadows'."
  ),
  broadType: listedFileText('broadType').description(
    "Baseline broad habitat type, e.g. 'Grassland'."
  ),
  distinctiveness: Joi.string()
    .allow(null, '')
    .description(
      "Distinctiveness band resolved by bng-library/metric from the habitat type, e.g. 'High'. Set once the habitat type is recognised."
    ),
  distinctivenessScore: Joi.number()
    .allow(null)
    .description(DISTINCTIVENESS_SCORE_DESCRIPTION),
  condition: listedFileText('condition').description(
    "Baseline condition assessment, e.g. 'Good'."
  ),
  conditionScore: Joi.number()
    .allow(null)
    .description(
      'Numeric condition score from bng-library/metric. Set during import enrichment and on habitat edits.'
    ),
  strategicSignificance: listedFileText('strategicSignificance').description(
    BASELINE_STRATEGIC_SIGNIFICANCE_DESCRIPTION
  ),
  retentionCategory: listedFileText('retentionCategory').description(
    RETENTION_CATEGORY_DESCRIPTION
  ),
  irreplaceable: Joi.boolean().description(
    'Whether the habitat is irreplaceable, from the BNG Service template\'s Irreplaceable Habitat column: true for "Yes", false for "No" or a blank cell (BMD-1083). Absent on a legacy upload, whose template has no such column.'
  ),
  area: Joi.number()
    .allow(null)
    .description(
      'Parcel area in square metres, rounded to the nearest integer, for display. Units are calculated from the unrounded sizeSquareMetres.'
    ),
  sizeSquareMetres: Joi.number()
    .allow(null)
    .description(
      'Parcel area in square metres, measured from the geometry (bng-library/measure), unrounded. Units are priced on it.'
    ),
  status: Joi.string()
    .valid('Complete', 'Incomplete')
    .required()
    .description(BASELINE_STATUS_DESCRIPTION),
  units: Joi.number()
    .allow(null)
    .description(
      'Baseline biodiversity units for the parcel, or null when required calculation inputs are missing. Written by both the import/enrichment path and the habitat-edit endpoint; read by the frontend display and the baseline unit totals.'
    ),
  ...metadataSchemaKeys(),
  properties: Joi.object()
    .unknown(true)
    .description(
      'Raw attribute columns copied verbatim from the GeoPackage Habitats layer.'
    )
}).description('An area (polygon) habitat parcel.')

// An individual tree (Urban Trees layer). Treated as a special area habitat, so
// it reuses habitatSchema's derived block (distinctiveness, condition scores,
// units, status, metadata) verbatim — only the parcel-specific descriptions are
// overridden and the tree-specific source columns appended. Deriving from
// habitatSchema avoids duplicating the shared field definitions.
const treeSchema = habitatSchema
  .append({
    featureId: Joi.string()
      .uuid()
      .required()
      .description(featureIdDescription('bng.baseline_trees')),
    ref: shortFileText().description(
      'Tree reference from the GeoPackage (Tree Ref column).'
    ),
    type: shortFileText().description(
      "Tree habitat type — 'Urban tree' or 'Rural tree', derived from the Rural or Urban Tree column."
    ),
    broadType: listedFileText('broadType').description(
      "Always 'Individual trees' for tree features."
    ),
    distinctiveness: Joi.string()
      .allow(null, '')
      .description(
        'Distinctiveness band resolved by bng-library/metric from the tree habitat type. Trees are Medium distinctiveness.'
      ),
    area: Joi.number()
      .allow(null)
      .description(
        'Notional tree area in square metres: the per-size reference area times the Count column, rounded. This is the value fed to the unit calculation.'
      ),
    sizeSquareMetres: Joi.number()
      .allow(null)
      .description(
        'Notional tree area in square metres: the per-size reference area times the Count column.'
      ),
    irreplaceable: Joi.boolean().description(
      "Whether the tree is irreplaceable, from the BNG Service template's Irreplaceable Habitat column: always false, as a file with a tree whose Irreplaceable Habitat is not 'No' is refused (IRREPLACEABLE_TREE). Absent on a legacy upload, whose template has no such column."
    ),
    units: Joi.number()
      .allow(null)
      .description(
        'Baseline biodiversity units for the tree, from bng-library/metric using the area-habitat calculation; null when required calculation inputs are missing.'
      ),
    properties: Joi.object()
      .unknown(true)
      .description(
        'Raw attribute columns copied verbatim from the GeoPackage Urban Trees layer.'
      ),
    // Tree-specific source columns not present on parcels.
    treeSize: listedFileText('treeSize').description(
      "Tree size band from the GeoPackage (Baseline/Proposed Tree Size), e.g. 'Medium'. Determines the per-tree area."
    ),
    treeSpecies: listedFileText('treeSpecies').description(
      "Tree type from the GeoPackage (Baseline/Proposed Tree Type column). One of the values the template's Tree Type list offers, as the upload checks it, or blank."
    ),
    ruralOrUrban: listedFileText('ruralOrUrban').description(
      'Rural or Urban Tree value as written in the GeoPackage (e.g. "Urban tree"). One of the values the template\'s list offers, as the upload checks it, or blank.'
    ),
    count: Joi.number()
      .allow(null)
      .description(
        'Count column from the GeoPackage: the number of trees the point stands for. The area and units are priced for that many trees; a blank count is priced as one tree, and any other value that is not a whole number of trees is refused at upload (TREE_COUNT_NOT_WHOLE).'
      )
  })
  .description('An individual tree feature (point).')

// A vertical area habitat (green wall or intertidal hard structure), drawn in
// the BNG Service template as a line along its base. An area habitat in every
// respect but its size, so it reuses habitatSchema; only the size and source
// descriptions differ.
const verticalHabitatSchema = habitatSchema
  .append({
    featureId: Joi.string()
      .uuid()
      .required()
      .description(featureIdDescription('bng.baseline_vertical_habitats')),
    ref: shortFileText().description(
      'Habitat reference from the GeoPackage (Habitat Ref column).'
    ),
    type: shortFileText().description(
      "Baseline habitat type: one of the five the Metric counts by vertical area, e.g. 'Facade-bound green wall'."
    ),
    broadType: listedFileText('broadType').description(
      "Baseline broad habitat type: 'Urban' or 'Intertidal hard structures'."
    ),
    area: Joi.number()
      .allow(null)
      .description(
        'Area in square metres, converted from the hectares typed: the same value as sizeSquareMetres, not rounded to the square metre, so an area under half a square metre does not show as 0.'
      ),
    sizeSquareMetres: Joi.number()
      .allow(null)
      .description(
        "Area in square metres, converted from the hectares the surveyor estimated on site and typed into the template's Area (ha) column; a line cannot give it. Units are priced on it, in hectares. Null when it is not a number above 0, which the upload refuses (VERTICAL_HABITAT_AREA_NOT_POSITIVE)."
      ),
    units: Joi.number()
      .allow(null)
      .description(
        'Baseline biodiversity units for the vertical area habitat, from bng-library/metric using the area-habitat calculation; null when required calculation inputs are missing.'
      ),
    properties: Joi.object()
      .unknown(true)
      .description(
        'Raw attribute columns copied verbatim from the GeoPackage Vertical Area Habitats Baseline layer.'
      )
  })
  .description(
    'A vertical area habitat (green wall or intertidal hard structure), drawn as a line along its base.'
  )

// Hedgerows and watercourses share the same linear-feature shape. This factory
// keeps their field order and prose identical while letting each supply its own
// descriptions and module-specific fields. Field order is significant — it
// drives the generated data dictionary — so `afterCondition` and
// `beforeProperties` splice extra keys into the exact positions each module
// uses.
function linearFeatureSchema({
  geometryRow,
  typeDescription,
  conditionDescription,
  afterCondition = {},
  distinctivenessDescription,
  statusDescription,
  unitsDescription,
  beforeProperties = {},
  propertiesDescription,
  rootDescription
}) {
  return Joi.object({
    featureId: Joi.string()
      .uuid()
      .required()
      .description(featureIdDescription(geometryRow)),
    ref: shortFileText().description(
      'Feature reference from the GeoPackage (Parcel Ref column).'
    ),
    type: shortFileText().description(typeDescription),
    condition: listedFileText('condition').description(conditionDescription),
    ...afterCondition,
    distinctiveness: Joi.string()
      .allow(null, '')
      .description(distinctivenessDescription),
    distinctivenessScore: Joi.number()
      .allow(null)
      .description(DISTINCTIVENESS_SCORE_DESCRIPTION),
    conditionScore: Joi.number()
      .allow(null)
      .description('Numeric condition score from bng-library/metric.'),
    length: Joi.number()
      .allow(null)
      .description(
        'Length in metres (measured size, rounded), for display. Set during unit enrichment; units are calculated from the unrounded sizeMetres.'
      ),
    sizeMetres: Joi.number()
      .allow(null)
      .description(
        'Length in metres, measured from the geometry (bng-library/measure), unrounded. Units are priced on it.'
      ),
    status: Joi.string()
      .valid('Complete', 'Incomplete')
      .required()
      .description(statusDescription),
    units: Joi.number()
      .allow(null)
      .description(
        `${unitsDescription} Null when required calculation inputs are missing.`
      ),
    strategicSignificance: listedFileText('strategicSignificance').description(
      BASELINE_STRATEGIC_SIGNIFICANCE_DESCRIPTION
    ),
    retentionCategory: listedFileText('retentionCategory').description(
      RETENTION_CATEGORY_DESCRIPTION
    ),
    ...metadataSchemaKeys(),
    ...beforeProperties,
    properties: Joi.object().unknown(true).description(propertiesDescription)
  }).description(rootDescription)
}

const linearHabitatSchema = linearFeatureSchema({
  geometryRow: 'bng.baseline_hedgerows',
  typeDescription: 'Hedgerow type (Baseline Hedge Type column).',
  conditionDescription: 'Hedgerow condition assessment.',
  distinctivenessDescription:
    'Distinctiveness band resolved by bng-library/metric from the hedgerow type.',
  statusDescription: BASELINE_STATUS_DESCRIPTION,
  unitsDescription:
    'Baseline biodiversity units for the hedgerow, from bng-library/metric (BMD-427/428).',
  propertiesDescription:
    'Raw attribute columns copied verbatim from the GeoPackage Hedgerows layer.',
  rootDescription: 'A hedgerow (linear) feature.'
})

const watercourseHabitatSchema = linearFeatureSchema({
  geometryRow: 'bng.baseline_watercourses',
  typeDescription: 'Watercourse type (Baseline River Type column).',
  conditionDescription: 'Watercourse condition assessment.',
  afterCondition: {
    riparianEncroachment: listedFileText('riparianEncroachment').description(
      'Riparian-zone encroachment category from the GeoPackage.'
    ),
    watercourseEncroachment: listedFileText(
      'watercourseEncroachment'
    ).description('Watercourse encroachment category from the GeoPackage.')
  },
  distinctivenessDescription:
    'Distinctiveness band resolved by bng-library/metric from the watercourse type.',
  statusDescription: BASELINE_STATUS_DESCRIPTION,
  unitsDescription:
    'Baseline biodiversity units for the watercourse, from bng-library/metric (BMD-427/428).',
  beforeProperties: {
    enhancementType: listedFileText('enhancementType').description(
      'Enhancement type from the GeoPackage Rivers layer.'
    ),
    waterEncroachmentMultiplier: Joi.number()
      .allow(null)
      .description(
        'Watercourse-encroachment multiplier applied by bng-library/metric when computing units.'
      ),
    riparianEncroachmentMultiplier: Joi.number()
      .allow(null)
      .description(
        'Riparian-encroachment multiplier applied by bng-library/metric when computing units.'
      )
  },
  propertiesDescription:
    'Raw attribute columns copied verbatim from the GeoPackage Watercourses layer.',
  rootDescription: 'A watercourse (linear) feature.'
})

// The project details page's limits (BMD-849), which it also sets on its
// inputs.
const PROJECT_DETAILS_PERSON_MAX_LENGTH = 255
const PLANNING_APPLICATION_REFERENCE_MAX_LENGTH = 50
const PLANNING_APPLICATION_TYPE_MAX_LENGTH = 100

const projectDetailsSchema = Joi.object({
  localPlanningAuthority: Joi.string()
    .allow(null, '')
    .description('Local Planning Authority name.'),
  localPlanningAuthorityReference: Joi.string()
    .pattern(/^E600\d{5}$/)
    .allow(null)
    .description(
      'Planning Data reference for the selected Local Planning Authority; absent on legacy free-text records.'
    ),
  surveyCompleters: Joi.string()
    .max(PROJECT_DETAILS_PERSON_MAX_LENGTH)
    .allow(null, '')
    .description('Names of survey completer(s).'),
  surveyCompletionDate: Joi.string()
    .pattern(/^\d{2}\/\d{2}\/\d{4}$/)
    .allow(null, '')
    .description('Survey completion date in DD/MM/YYYY format.'),
  developmentType: Joi.string()
    .valid('Small site', 'Large site')
    .allow(null)
    .description('Development type classification.'),
  nsips: Joi.string()
    .valid('Yes', 'No')
    .allow(null)
    .description(
      'Whether the project is a National Significant Infrastructure Project.'
    ),
  applicant: Joi.string()
    .max(PROJECT_DETAILS_PERSON_MAX_LENGTH)
    .allow(null, '')
    .description(
      'Name of the applicant for planning permission: a person and/or a company.'
    ),
  planningApplicationReference: Joi.string()
    .max(PLANNING_APPLICATION_REFERENCE_MAX_LENGTH)
    .allow(null, '')
    .description(
      "The planning application's reference, in whatever form the local planning authority gives it."
    ),
  planningApplicationType: Joi.string()
    .max(PLANNING_APPLICATION_TYPE_MAX_LENGTH)
    .allow(null, '')
    .description(
      'The type of planning application, as the user words it, such as "Outline planning permission".'
    )
}).description('Project details entered by the user.')

const habitatDataSchema = Joi.object({
  ...featureDataEnvelopeFields,
  redLine: redLineSchema,
  habitats: Joi.array()
    .items(habitatSchema)
    .description('Area (polygon) habitat parcels in the baseline.'),
  trees: Joi.array()
    .items(treeSchema)
    .description('Individual tree (point) features in the baseline.'),
  verticalHabitats: Joi.array()
    .items(verticalHabitatSchema)
    .description(
      'Vertical area habitats (green walls and intertidal hard structures) in the baseline. Read from a BNG Service template file only: empty for a legacy upload, and absent on a document saved before vertical area habitats were read.'
    ),
  hedgerows: Joi.array()
    .items(linearHabitatSchema)
    .description('Hedgerow (linear) features in the baseline.'),
  watercourses: Joi.array()
    .items(watercourseHabitatSchema)
    .description('Watercourse (linear) features in the baseline.'),
  habitatSizes: habitatSizesSummarySchema,
  units: baselineUnitsTotalsSchema
}).description(
  'Imported baseline state: features, sizes and unit totals. Written by the baseline upload flow.'
)

const projectSchema = Joi.object({
  name: Joi.string().description(
    'Project name shown to the user; editable via PATCH /projects/{id} and, with the other details, PATCH /projects/{id}/details.'
  ),
  site: siteSchema,
  units: unitsSchema,
  details: projectDetailsSchema.allow(null),
  baseline: habitatDataSchema,
  postIntervention: postInterventionDataSchema
}).description(
  'Root document stored in the bng.projects.project JSONB column (and snapshotted into bng.audit_log.project).'
)

export {
  projectSchema,
  projectDetailsSchema,
  siteSchema,
  unitsSchema,
  baselineUnitsTotalsSchema,
  habitatDataSchema,
  habitatSchema,
  treeSchema,
  verticalHabitatSchema,
  linearHabitatSchema,
  watercourseHabitatSchema,
  postInterventionDataSchema
}
